mapper.select:
SELECT 
FROM TBL_INFLUENCE_FACTOR
WHERE IS_DELETED = 0

    AND TENANT_ID = #{param.tenantId}


    AND BOOK_ID = #{param.bookId}


    AND FACTOR_CODE LIKE CONCAT('%', #{param.factorCode}, '%')


    AND FACTOR_NAME LIKE CONCAT('%', #{param.factorName}, '%')


    AND FACTOR_TYPE = #{param.factorType}


    AND DATA_TYPE = #{param.dataType}


    AND IS_ENABLED = #{param.isEnabled}

ORDER BY PRIORITY_LEVEL ASC, CREATE_TIME DESC

SELECT 
FROM TBL_INFLUENCE_FACTOR
WHERE FACTOR_CODE = #{factorCode}
AND TENANT_ID = #{tenantId}
AND BOOK_ID = #{bookId}
AND IS_DELETED = 0
LIMIT 1

SELECT 
FROM TBL_INFLUENCE_FACTOR
WHERE FACTOR_TYPE = #{factorType}
AND TENANT_ID = #{tenantId}
AND BOOK_ID = #{bookId}
AND IS_DELETED = 0
AND IS_ENABLED = 1
ORDER BY PRIORITY_LEVEL ASC, FACTOR_CODE ASC

SELECT COUNT(1)
FROM TBL_INFLUENCE_FACTOR
WHERE FACTOR_CODE = #{factorCode}
AND TENANT_ID = #{tenantId}
AND BOOK_ID = #{bookId}
AND IS_DELETED = 0

    AND FACTOR_ID != #{excludeId}

SELECT MAX(PRIORITY_LEVEL)
FROM TBL_INFLUENCE_FACTOR
WHERE TENANT_ID = #{tenantId}
AND BOOK_ID = #{bookId}
AND IS_DELETED = 0

mapper.update:
UPDATE TBL_INFLUENCE_FACTOR SET IS_ENABLED = #{isEnabled}, UPDATE_TIME = NOW(), UPDATE_BY = #{updateBy} WHERE ID IN
#{factorId}
AND IS_DELETED = 0

UPDATE TBL_INFLUENCE_FACTOR SET IS_DELETED = 1, UPDATE_TIME = NOW(), UPDATE_BY = #{updateBy} WHERE ID IN
#{factorId}
AND IS_DELETED = 0
